#déterminer le plus petit commun multiple de deux entiers naturels non nuls

def Saisie():
    b = False
    while not(b) :
        n=int(input("Donner un entier naturel : "))
        b = n != 0
    return n

def PPCM(x,y):
    sx = x     
    sy = y
    while (sy != sx) :
        if sx < sy :
            sx = sx + x
        else:
            sy = sy + y
    
    return sx

#############################PP#############################
a = Saisie()
b = Saisie()
print("ppcm (",a,",",b,")=",PPCM(a,b))

